import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"@pumpkin-plugins/plugin-kit","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/plugin-kit/README.md"},"headers":[],"relativePath":"tools/plugin-kit/README.md","filePath":"tools/plugin-kit/README.md","lastUpdated":1792508829000}`),a={name:`tools/plugin-kit/README.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pumpkin-plugins-plugin-kit" tabindex="-1">@pumpkin-plugins/plugin-kit <a class="header-anchor" href="#pumpkin-plugins-plugin-kit" aria-label="Permalink to “@pumpkin-plugins/plugin-kit”">​</a></h1><p><a href="https://www.npmjs.com/package/@pumpkin-plugins/plugin-kit" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/%40pumpkin-plugins%2Fplugin-kit" alt="npm downloads"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/plugin-kit" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/v/%40pumpkin-plugins%2Fplugin-kit?label=latest%20release" alt="latest npm release"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/plugin-kit" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/l/%40pumpkin-plugins%2Fplugin-kit" alt="npm license"></a></p><p>Shared building blocks for Pumpkin plugins: a plugin base class and registration wrapper, data folders, logging, scheduled tasks, command registration, plugin messages and binary payload encoders, plus in-memory fakes for tests. <code>PluginBase</code> builds Pumpkin metadata from your <code>PluginInfo</code>, and <code>registerPlugin</code> starts the non-blocking Pumpkin Market update check after the plugin loads.</p><p>The kit keeps its own handler ids for scheduled tasks and commands, and Pumpkin&#39;s API package doesn&#39;t know them. Export the kit&#39;s dispatchers from your entry point so Pumpkin&#39;s callbacks reach them:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { handleCommand, handleTask } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pumpkin-plugins/plugin-kit/plugin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@pumpkin-plugins/pumpkin-api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The named exports replace the API package&#39;s <code>handleCommand</code> and <code>handleTask</code>, which <code>export *</code> would otherwise re-export. Without them, commands registered with <code>registerCommands</code> fail with <code>No handler for command ID</code>, and the kit&#39;s scheduled tasks, including the update check, never run.</p><p>The <a href="./docs/">plugin-kit guide</a> covers the lifecycle, scheduling, data folders, commands and test fakes. <a href="/pumpkin-plugins/guides/plugin-info-and-readmes">Plugin info and READMEs</a> explains <code>PluginInfo</code> and command declarations, and the <a href="/pumpkin-plugins/guides/code-style">code style guide</a> covers shared conventions such as log colors.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/tools/plugin-kit/docs/" target="_blank" rel="noreferrer">tool guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/tools/@pumpkin-plugins/plugin-kit/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};